"""Official Ceph16.2.15 offline map algorithms, not an emulated or live cluster."""
import hashlib,json,pathlib,re,subprocess,tempfile
def run(tool,*args):
 result=subprocess.run([tool,*map(str,args)],capture_output=True,text=True,timeout=15)
 if result.returncode:raise RuntimeError('private Ceph map operation failed: '+result.stderr[-1800:])
 return result.stdout,result.stderr
def dump(tool,*args):
 text=run(tool,*args)[0]
 if '{' not in text:raise RuntimeError('Ceph map JSON missing')
 return json.loads(text[text.index('{'):])
def mappings(path,rule=0):
 out,err=run('crushtool','-i',path,'--test','--rule',rule,'--num-rep','2','--min-x','0','--max-x','255','--show-mappings')
 values={int(x):json.loads(devices) for x,devices in re.findall(r'CRUSH rule \d+ x (\d+) (\[[^\]]*\])',out+err)}
 if set(values)!=set(range(256)):raise RuntimeError('finite CRUSH mapping incomplete')
 return values
def weight(path):
 data=dump('crushtool','-i',path,'--dump','--format','json')
 return next(item['weight']/65536 for bucket in data['buckets'] for item in bucket['items'] if item['id']==0)
class CephMaps:
 def __enter__(self):
  assert 'ceph version 16.2.15 ' in run('osdmaptool','--version')[0]
  self.temp=tempfile.TemporaryDirectory(prefix='of-ceph-maps-');self.root=pathlib.Path(self.temp.name)
  try:
   self.original=self.root/'original.crush';self.classified=self.root/'classified.crush';text=self.root/'map.txt'
   run('crushtool','--build','--num_osds','6','host','straw2','2','root','straw2','0','-o',self.original)
   run('crushtool','-d',self.original,'-o',text);source=text.read_text()
   for i in range(6):source=re.sub(r'(?m)^device '+str(i)+r' osd\.'+str(i)+r'$',lambda m:m[0]+' class '+('ssd' if i%2==0 else 'hdd'),source)
   text.write_text(source);run('crushtool','-c',text,'-o',self.classified)
   self.osdmap=self.root/'original.osdmap';run('osdmaptool','--createsimple','6','--with-default-pool',self.osdmap)
   print('NATIVE_CEPH_MAP_TOOLS_READY:16.2.15',flush=True);return self
  except BaseException:self.temp.cleanup();raise
 def __exit__(self,*args):self.temp.cleanup()

