import subprocess,json,pathlib,shutil
def inspect(original,candidate,directory):
    def call(*args):
        result=subprocess.run(list(map(str,args)),capture_output=True,text=True,timeout=10)
        if result.returncode:raise RuntimeError('approved map inspection failed')
        return result.stdout
    def decode(text):return json.loads(text[text.index('{'):])
    def view(path,name,*flags):
        exported=pathlib.Path(directory)/name
        state=decode(call('osdmaptool','--mark-up-in',*flags,'--export-crush',exported,'--dump','json',path))
        data=decode(call('crushtool','-i',exported,'--dump','--format','json'))
        capacity=next(item['weight']/65536 for bucket in data['buckets'] for item in bucket['items'] if item['id']==0)
        return {'osd_weight':state['osds'][0]['weight'],'crush_weight':capacity}
    initial=view(original,'base.crush')
    temporary=view(original,'temporary.crush','--mark-out','0')
    shutil.copyfile(original,candidate)
    call('osdmaptool','--adjust-crush-weight','0:0','--save',candidate)
    changed=view(candidate,'changed.crush','--adjust-crush-weight','0:0')
    return {'baseline':initial,'temporary_out':temporary,'crush_changed':changed}
```

